begin;
create function pg_temp.check_accounting(ok boolean,label text) returns void language plpgsql as $$begin if ok is not true then raise exception 'FAIL: %',label;end if;end $$;
create function pg_temp.reject_accounting(q text,expected text) returns void language plpgsql as $$begin
 begin execute q;exception when others then if position(lower(expected) in lower(sqlerrm))=0 then raise exception 'Expected %; got %',expected,sqlerrm;end if;return;end;
 raise exception 'Expected rejection: %',expected;end $$;
grant execute on function pg_temp.check_accounting(boolean,text),pg_temp.reject_accounting(text,text) to authenticated;
insert into auth.users(id,email,is_anonymous) values('a9010000-0000-4000-8000-000000000001','accounting-owner@example.invalid',false),('a9020000-0000-4000-8000-000000000001','accounting-other@example.invalid',false);
set local role authenticated;
select set_config('request.jwt.claim.sub','a9010000-0000-4000-8000-000000000001',true);
select public.setup_business('Accounting SQL disposable A','Owner A');
select set_config('request.jwt.claim.sub','a9020000-0000-4000-8000-000000000001',true);
select public.setup_business('Accounting SQL disposable B','Owner B');
reset role;
select set_config('request.jwt.claim.sub','',true);
create temp table accounting_context as select tenant_id,(select tenant_id from public.user_profiles where user_id='a9020000-0000-4000-8000-000000000001') other_tenant from public.user_profiles where user_id='a9010000-0000-4000-8000-000000000001';
grant select on accounting_context to authenticated;
insert into public.lpg_brands(tenant_id,brand_id,brand_name) select tenant_id,'a9030000-0000-4000-8000-000000000001','Accounting Brand' from accounting_context;
insert into public.items(tenant_id,item_id,brand_id,size_kg,mouth_size,empty_quantity,filled_quantity) select tenant_id,'a9040000-0000-4000-8000-000000000001','a9030000-0000-4000-8000-000000000001',12,'22mm',100,100 from accounting_context;
insert into public.lpg_brands(tenant_id,brand_id,brand_name) select tenant_id,'a9030000-0000-4000-8000-000000000002','Opening-price Brand' from accounting_context;
insert into public.items(tenant_id,item_id,brand_id,size_kg,mouth_size,empty_quantity,filled_quantity) select tenant_id,'a9040000-0000-4000-8000-000000000002','a9030000-0000-4000-8000-000000000002',12,'22mm',0,0 from accounting_context;
insert into public.gas_plants(tenant_id,plant_id,brand_id,plant_name) select tenant_id,'a9050000-0000-4000-8000-000000000001','a9030000-0000-4000-8000-000000000001','Accounting Plant' from accounting_context;
insert into public.price_books(tenant_id,item_id,customer_tier,price_type,price,effective_from) select tenant_id,'a9040000-0000-4000-8000-000000000001','retail','package',1000,now()-interval '1 day' from accounting_context;
set local role authenticated;
select set_config('request.jwt.claim.sub','a9010000-0000-4000-8000-000000000001',true);
do $$ declare d uuid;v uuid;tr uuid;pid uuid;sid uuid;cat uuid;cash uuid;bank uuid;r jsonb;body jsonb;req uuid;baseline numeric;rev integer;h uuid;today date:=(now() at time zone 'Asia/Dhaka')::date;hist jsonb;price jsonb;
begin
 perform pg_temp.check_accounting(not exists(select 1 from public.wallets where type='logistics'),'no Logistics wallet');
 -- An owner can establish a manual price before the first purchase. Restoring
 -- automatic mode must not convert missing purchase evidence into zero COGS.
 r:=public.set_product_buying_price('{"item_id":"a9040000-0000-4000-8000-000000000002","price_type":"package","is_manual":true,"price":400,"reason":"Opening manual price"}',gen_random_uuid());
 perform pg_temp.reject_accounting(format('select public.set_product_buying_price(%L,%L)',jsonb_build_object('item_id','a9040000-0000-4000-8000-000000000002','price_type','package','is_manual',false,'expected',r->>'history_id','reason','Restore without purchase evidence'),gen_random_uuid()),'No automatic buying price');
 price:=public.get_product_inventory('a9040000-0000-4000-8000-000000000002');
 perform pg_temp.check_accounting((select (x->>'price')::numeric from jsonb_array_elements(price->'buying_prices') x where x->>'type'='package')=400,'missing automatic calculation preserves intentional manual price');
 select wallet_id into cash from public.get_payment_wallets() where type='cash';select wallet_id into bank from public.get_payment_wallets() where type='dealership';
 d:=(public.save_employee(jsonb_build_object('name','Accounting Driver','phones',jsonb_build_array(jsonb_build_object('phone','01700000901','is_primary',true)),'business_unit','truck_business','employee_type_name','Driver','terms',jsonb_build_object('monthly_salary',0,'effective_from',today,'is_active',true)),gen_random_uuid())->>'employee_id')::uuid;
 v:=(public.save_vehicle(jsonb_build_object('name','Accounting Truck','serial_no','ACC-901','capacity',0,'driver_employee_id',d),gen_random_uuid())->>'vehicle_id')::uuid;
 select sum(balance) into baseline from public.wallets;
 pid:=(public.create_purchase(jsonb_build_object('request_id',gen_random_uuid(),'plant_id','a9050000-0000-4000-8000-000000000001','vehicle_id',v,'transport_cost',200,'labour_cost',100,'commission',0,'items',jsonb_build_array(
 jsonb_build_object('item_id','a9040000-0000-4000-8000-000000000001','type','refill','quantity',10,'empty_dispatched',10,'unit_price',100),jsonb_build_object('item_id','a9040000-0000-4000-8000-000000000001','type','package','quantity',10,'empty_dispatched',0,'unit_price',300))))->>'purchase_id')::uuid;
 perform public.dispatch_purchase(pid,1);
 perform pg_temp.check_accounting((select sum(balance) from public.wallets)=baseline,'dispatch makes no wallet movement');
 r:=public.get_purchase_settlement(pid);perform pg_temp.check_accounting((r->>'due')::numeric=4100 and (r->>'allocated_transport')::numeric=200,'external purchase payable excludes transport');
 perform public.receive_purchase(pid,2);
 price:=public.get_product_inventory('a9040000-0000-4000-8000-000000000001');
 perform pg_temp.check_accounting((select (x->>'price')::numeric from jsonb_array_elements(price->'buying_prices') x where x->>'type'='refill')=115,'unpaid receipt updates refill price');
 perform pg_temp.check_accounting((select (x->>'price')::numeric from jsonb_array_elements(price->'buying_prices') x where x->>'type'='package')=315,'package price includes allocated overhead');
 hist:=public.get_buying_price_history('a9040000-0000-4000-8000-000000000001',0,1);perform pg_temp.check_accounting((hist->>'total')::int=2 and jsonb_array_length(hist->'entries')=1,'server price history pagination');
 select (x->>'history_id')::uuid into h from jsonb_array_elements(price->'buying_prices') x where x->>'type'='refill';
 body:=jsonb_build_object('item_id','a9040000-0000-4000-8000-000000000001','price_type','refill','expected',h,'is_manual',true,'price',120,'reason','Audited manual cost');req:=gen_random_uuid();r:=public.set_product_buying_price(body,req);
 perform pg_temp.check_accounting(public.set_product_buying_price(body,req)=r,'manual buying price retry returns original');
 perform public.set_product_commissions('a9040000-0000-4000-8000-000000000001',10,20,null);
 price:=public.get_product_inventory('a9040000-0000-4000-8000-000000000001');
 perform pg_temp.check_accounting((select (x->>'price')::numeric from jsonb_array_elements(price->'buying_prices') x where x->>'type'='refill')=120,'commission preserves manual override');
 perform pg_temp.check_accounting((select (x->>'automatic_price')::numeric from jsonb_array_elements(price->'buying_prices') x where x->>'type'='refill')=105,'override retains updated automatic calculation');
 perform pg_temp.check_accounting((select (x->>'price')::numeric from jsonb_array_elements(price->'buying_prices') x where x->>'type'='package')=295,'package commission recalculates independently');
 select (x->>'history_id')::uuid into h from jsonb_array_elements(price->'buying_prices') x where x->>'type'='refill';
 r:=public.set_product_buying_price(jsonb_build_object('item_id','a9040000-0000-4000-8000-000000000001','price_type','refill','expected',h,'is_manual',false,'reason','Restore received-purchase calculation'),gen_random_uuid());
 price:=public.get_product_inventory('a9040000-0000-4000-8000-000000000001');
 perform pg_temp.check_accounting((select (x->>'price')::numeric from jsonb_array_elements(price->'buying_prices') x where x->>'type'='refill')=105,'explicit restore uses available automatic calculation');
 perform public.set_product_buying_price(jsonb_build_object('item_id','a9040000-0000-4000-8000-000000000001','price_type','refill','expected',r->>'history_id','is_manual',true,'price',120,'reason','Reinstate intentional manual price'),gen_random_uuid());
 r:=public.get_inventory_valuation();perform pg_temp.check_accounting((r->>'known_value')::numeric=120*295+90*175,'filled and empty valuation use effective costs');
 perform public.record_purchase_payment(pid,jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',1000),jsonb_build_object('wallet_id',bank,'amount',3100)),gen_random_uuid());
 perform pg_temp.check_accounting((public.get_purchase_settlement(pid)->>'due')::numeric=0,'purchase split settlement');
 perform pg_temp.reject_accounting(format('select public.update_purchase(%L,%L,4)',pid,'{"labour_cost":200}'),'locked');
 -- Custom revenue is earned without collection, all incurred costs affect profit.
 tr:=(public.create_custom_transit(jsonb_build_object('vehicle_id',v,'fee',1000,'client_name','Accounting client','destination','Dhaka'),gen_random_uuid())->>'transit_id')::uuid;
 perform public.save_transit_costs(tr,'{"driver_cost":200,"helper_cost":0,"oil_cost":100,"others_cost":0,"additional_costs":[]}',1);
 r:=public.get_transit(tr);perform pg_temp.check_accounting((r->>'profit')::numeric=700 and (r->>'outstanding')::numeric=300,'profit includes all unpaid costs');
 perform pg_temp.reject_accounting(format('select public.transition_transit(%L,''complete'',2)',tr),'outstanding');
 body:=jsonb_build_object('transit_id',tr,'kind','expense','payment_date',today,'payments',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',40),jsonb_build_object('wallet_id',bank,'amount',60)));req:=gen_random_uuid();r:=public.record_operating_payment(body,req);
 perform pg_temp.check_accounting(public.record_operating_payment(body,req)=r,'operating split payment idempotency');
 perform public.record_operating_payment(jsonb_build_object('transit_id',tr,'kind','client_receipt','payment_date',today,'payments',jsonb_build_array(jsonb_build_object('wallet_id',bank,'amount',500))),gen_random_uuid());
 perform public.employee_payment_operation(jsonb_build_object('action','pay','items',jsonb_build_array(jsonb_build_object('employee_id',d,'kind','trips','trip_count',1,'transit_id',tr,'trip_role','driver','payment_date',today,'payments',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',100),jsonb_build_object('wallet_id',bank,'amount',100))))),gen_random_uuid());
 r:=public.get_transit(tr);perform pg_temp.check_accounting((r->>'profit')::numeric=700 and (r->>'outstanding')::numeric=0,'payments do not alter incurred profit');
 perform public.transition_transit(tr,'return',(r->>'revision')::integer);
 r:=public.get_transit(tr);perform public.transition_transit(tr,'complete',(r->>'revision')::integer);
 select category_id into cat from public.get_vehicle_expense_categories() where name='Engine Oil';
 body:=jsonb_build_object('vehicle_id',v,'title','Accounting service','service_date',today,'expenses',jsonb_build_array(jsonb_build_object('category_id',cat,'amount',300,'description','Oil change')));req:=gen_random_uuid();r:=public.save_service_trip(body,req);sid:=(r->>'service_trip_id')::uuid;
 perform pg_temp.check_accounting(public.save_service_trip(body,req)=r,'service save idempotency');
 perform public.record_operating_payment(jsonb_build_object('service_trip_id',sid,'kind','expense','payment_date',today,'payments',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',200),jsonb_build_object('wallet_id',bank,'amount',200))),gen_random_uuid());
 r:=public.get_service_trip(sid);perform pg_temp.check_accounting((r->>'advance')::numeric=100 and (r->>'outstanding')::numeric=0,'service advance is tracked');
 perform pg_temp.reject_accounting(format('select public.finalize_service_trip(%L,2,%L)',sid,gen_random_uuid()),'surplus');
 hist:=public.get_operating_payments(null,sid,0,1);perform pg_temp.check_accounting((hist->>'total')::int=2 and jsonb_array_length(hist->'entries')=1,'payment pagination');
 perform public.record_operating_payment(jsonb_build_object('service_trip_id',sid,'kind','expense_return','return_of',hist->'entries'->0->>'payment_id','payment_date',today,'payments',jsonb_build_array(jsonb_build_object('wallet_id',hist->'entries'->0->>'wallet_id','amount',100))),gen_random_uuid());
 r:=public.get_service_trip(sid);perform public.finalize_service_trip(sid,(r->>'revision')::int,gen_random_uuid());
 r:=public.get_finance_analysis(jsonb_build_object('from',today,'to',today,'grain','day'));
 perform pg_temp.check_accounting((r->'totals'->>'revenue')::numeric=1000,'internal purchase transport excluded from consolidated revenue');
 perform pg_temp.check_accounting((r->'totals'->>'expenses')::numeric=600,'transit crew and service costs counted once');
 perform pg_temp.check_accounting((r->'totals'->>'cash_in')::numeric=600 and (r->'totals'->>'cash_out')::numeric=4800,'cash receipts, advances and payments are distinct');
 perform pg_temp.check_accounting(jsonb_array_length(r->'trend')=1,'daily trend complete');
 perform pg_temp.check_accounting((public.get_analysis_details(jsonb_build_object('from',today,'to',today),'expense',null,0,1)->>'total')::int>=3,'bounded analytics drill-down');
 perform pg_temp.check_accounting((public.get_service_trip_directory(jsonb_build_object('vehicle_id',v,'category_id',cat),0,1)->>'total')::int=1,'service category directory filter');
 perform pg_temp.reject_accounting(format('select public.get_finance_analysis(%L)',jsonb_build_object('from',today,'to',today,'business_id',(select other_tenant from accounting_context))),'authorized');
 -- Sale costs remain fixed after later manual buying-price changes.
 perform public.create_pos_sale('01700000909','Cost evidence customer',null,null,'retail',0,0,null,'[{"item_id":"a9040000-0000-4000-8000-000000000001","type":"package","quantity":1,"unit_price":1000}]',null,gen_random_uuid(),'[]');
 price:=public.get_product_inventory('a9040000-0000-4000-8000-000000000001');select (x->>'history_id')::uuid into h from jsonb_array_elements(price->'buying_prices') x where x->>'type'='package';
 perform public.set_product_buying_price(jsonb_build_object('item_id','a9040000-0000-4000-8000-000000000001','price_type','package','expected',h,'is_manual',true,'price',500,'reason','Later owner override'),gen_random_uuid());
 r:=public.get_finance_analysis(jsonb_build_object('from',today,'to',today,'grain','day'));
 perform pg_temp.check_accounting((r->'totals'->>'expenses')::numeric=885 and (r->'totals'->>'profit')::numeric=1115,'sale captures external cost 285; later buying price does not rewrite profit');
 perform pg_temp.check_accounting((r->'vehicles'->0->>'expenses')::numeric=600 and (r->'vehicles'->0->>'service_expenses')::numeric=300,'vehicle service costs counted once across multiple transits');
 perform pg_temp.check_accounting((public.get_financial_activity('{"source":"purchase"}',0,1)->>'total')::int=1,'Finance groups purchase under one activity');
 perform pg_temp.check_accounting((public.get_financial_activity_wallets('purchase',pid,0,1)->>'total')::int=2,'purchase wallet audit preserves individual split entries');
 -- Cross-business access must come from an explicit trusted OWNER grant.
 perform public.grant_business_analysis_access('a9020000-0000-4000-8000-000000000001',true);
 perform set_config('request.jwt.claim.sub','a9020000-0000-4000-8000-000000000001',true);
 perform pg_temp.check_accounting((select count(*) from public.get_analysis_businesses())=2,'explicit cross-business scope');
 r:=public.get_finance_analysis(jsonb_build_object('from',today,'to',today,'grain','day'));
 perform pg_temp.check_accounting(jsonb_array_length(r->'businesses')=2 and (r->'totals'->>'revenue')::numeric=2000,'combined analysis uses only authorized businesses');
 perform set_config('request.jwt.claim.sub','a9010000-0000-4000-8000-000000000001',true);
 perform public.grant_business_analysis_access('a9020000-0000-4000-8000-000000000001',false);
 perform set_config('request.jwt.claim.sub','a9020000-0000-4000-8000-000000000001',true);
 perform pg_temp.reject_accounting(format('select public.get_finance_analysis(%L)',jsonb_build_object('from',today,'to',today,'business_id',(select tenant_id from accounting_context))),'authorized');
end $$;
reset role;
select set_config('request.jwt.claim.sub','',true);
insert into public.sales(tenant_id,sale_id,customer_id,status,total_amount,subtotal,created_at)
select tenant_id,'a9090000-0000-4000-8000-000000000001',(select customer_id from public.customers where tenant_id=c.tenant_id limit 1),'completed',500,500,'2024-01-15T12:00:00Z' from accounting_context c;
insert into public.sale_items(tenant_id,sale_item_id,sale_id,item_id,type,quantity,unit_price,line_total)
select tenant_id,'a9090000-0000-4000-8000-000000000002','a9090000-0000-4000-8000-000000000001','a9040000-0000-4000-8000-000000000001','package',1,500,500 from accounting_context;
set local role authenticated;
select set_config('request.jwt.claim.sub','a9010000-0000-4000-8000-000000000001',true);
do $$ declare r jsonb;begin
 r:=public.get_finance_analysis('{"from":"2024-01-01","to":"2024-01-31","grain":"month"}');
 perform pg_temp.check_accounting((r->'totals'->>'unvalued_units')::int=1 and r->'totals'->>'profit' is null,'unknown historical costs never use current buying prices or invented zero cost profit');
 perform pg_temp.reject_accounting('select * from public.product_buying_price_history','permission denied');
 perform pg_temp.reject_accounting('select * from public.operating_payments','permission denied');
 perform pg_temp.reject_accounting('select * from public.business_analysis_access','permission denied');
end $$;
reset role;
select pg_temp.check_accounting(not exists(select 1 from public.wallets w where w.balance<>w.opening_balance+coalesce((select sum(amount) from public.wallet_transactions x where x.tenant_id=w.tenant_id and x.wallet_id=w.wallet_id),0)),'all wallets reconcile');
select 'PASS: purchase allocations, buying prices/overrides/history, valuation, transit costs, split/advance/refund payments, analytics and pagination';
rollback;
